export const QUIZ_ITEMS = [
  { id: "1615", section: "الفرائض والمواريث", category: "المواريث", level: "متوسط", question: "ما موانع الإرث الثلاثة في الفقه الإسلامي؟", answer: "ثلاثة: 1- القتل العمد العدوان (القاتل لا يرث ممن قتله). 2- اختلاف الدين (المسلم لا يرث الكافر ولا الكافر المسلم بالإجماع). 3- الرق (العبد لا يرث ولا يُورَث في حكمه).", explanation: "يُستفاد منه في باب المواريث. يُستفاد منه في باب المواريث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1616", section: "الفرائض والمواريث", category: "الفروض", level: "صعب", question: "كم فريضة حددها القرآن الكريم في المواريث؟", answer: "ستة فروض مقدّرة: النصف (1/2)، الربع (1/4)، الثمن (1/8)، الثلثان (2/3)، الثلث (1/3)، السدس (1/6) — وكل منها لمستحق محدد بآيات النساء (11-12 و176).", explanation: "يُستفاد منه في باب الفروض. يُستفاد منه في باب الفروض مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1617", section: "الفرائض والمواريث", category: "الحجب", level: "صعب", question: "ما الفرق بين حجب الحرمان وحجب النقصان؟", answer: "حجب الحرمان: حجب الوارث كلياً عن الإرث — كحجب الأخ بالابن. حجب النقصان: نقل الوارث من فرض أعلى إلى أدنى — كانتقال الزوج من النصف (1/2) إلى الربع (1/4) عند وجود الولد.", explanation: "يُستفاد منه في باب الحجب. يُستفاد منه في باب الحجب مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1618", section: "الفرائض والمواريث", category: "أصحاب الفروض", level: "متوسط", question: "من الورثة الذين لا يُحجبون حجب حرمان أبداً؟", answer: "ستة: الأب، الأم، الابن، البنت، الزوج، الزوجة — لا يُحجبون حجب حرمان مطلقاً وإن نقص نصيبهم بحجب النقصان (كانتقال الزوج من النصف إلى الربع عند وجود الولد). أما ابن الابن (الحفيد) فليس منهم؛ إذ يُحجب حجب حرمان تاماً بوجود الابن.", explanation: "يُستفاد منه في باب أصحاب الفروض. يُستفاد منه في باب أصحاب الفروض مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1619", section: "الفرائض والمواريث", category: "الوصية", level: "متوسط", question: "ما أقصى ما يجوز للمسلم إيصاء به من ماله؟", answer: "لا تجوز الوصية بأكثر من ثلث المال للأجانب — لحديث سعد رضي الله عنه: «الثلث والثلث كثير» (البخاري). ولا تجوز الوصية لوارث ألبتة إلا بإجازة بقية الورثة.", explanation: "يُستفاد منه في باب الوصية. يُستفاد منه في باب الوصية مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1620", section: "الفرائض والمواريث", category: "الميراث", level: "متوسط", question: "من هم أصحاب الفروض المحددة في القرآن؟", answer: "أصحاب الفروض المقدَّرة في القرآن: 1) الزوج: النصف أو الربع. 2) الزوجة/الزوجات: الربع أو الثمن. 3) الأم: الثلث أو السدس. 4) الأب: السدس (عصبة). 5) البنت/البنات: النصف أو الثلثان. 6) الأخت الشقيقة: النصف أو الثلثان. 7) الجدة: السدس. 8) الأخ لأم والأخت لأم: السدس أو الثلث.", explanation: "يُستفاد منه في باب الميراث. يُستفاد منه في باب الميراث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1621", section: "الفرائض والمواريث", category: "الميراث", level: "متوسط", question: "من الذين يُحجَبون حجب حرمان من الميراث؟ اذكر أمثلة.", answer: "حجب الحرمان: حرمان الوارث من الإرث بسبب وجود وارث أقوى منه. أمثلة: 1) الجد يُحجَب بوجود الأب. 2) الإخوة يُحجَبون بوجود الابن أو الأب. 3) بنت الابن تُحجَب بوجود بنتين فأكثر إلا إذا وُجد معها ابن ابن. 4) الأخت لأم تُحجَب بوجود الفرع الوارث أو الأصل الذكر. والمانعون من الإرث: الكفر، والقتل العمد، والرق.", explanation: "يُستفاد منه في باب الميراث. يُستفاد منه في باب الميراث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1622", section: "الأسماء الحسنى", category: "شرح الأسماء", level: "متوسط", question: "ما الفرق بين اسمَي الله «الغفور» و«الغفّار»؟", answer: "الغفور: يدل على سعة المغفرة في ذاتها مهما عظمت الذنوب. الغفّار: يدل على كثرة المغفرة وتكرارها مراراً وتكراراً، أي كثير المغفرة لا ينضب عفوه. والاسمان معاً يُعطيان المؤمن رجاءً بسعة المغفرة واستمرارها مهما كان العبد مذنباً وكثُرت عودته بالتوبة.", explanation: "يُستفاد منه في باب شرح الأسماء. يُستفاد منه في باب شرح الأسماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1623", section: "الأسماء الحسنى", category: "شرح الأسماء", level: "سهل", question: "ما معنى اسم الله «الحليم» وكيف يُفرَّق بينه وبين الصبور؟", answer: "الحليم: الذي لا يستفزه عصيان العصاة ولا يُقلقه انتشار المعاصي، فيؤخر العقوبة رحمةً وحكمةً. الصبور في المقابل: يركز على التأخير الطويل مع الإحاطة بالخلق. الحليم يُشير إلى الطمأنينة التامة وعدم تغيّر حال الله بمعصية عبده.", explanation: "يُستفاد منه في باب شرح الأسماء. يُستفاد منه في باب شرح الأسماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1624", section: "الأسماء الحسنى", category: "شرح الأسماء", level: "متوسط", question: "ما معنى اسمَي الله «الوكيل» و«الكفيل»؟", answer: "الوكيل: الذي يتولى مصالح عباده ويكفيهم ما يهمهم. قال تعالى: ﴿وَكَفَىٰ بِاللَّهِ وَكِيلاً﴾. ومعناه التفويض التام إليه والاعتماد عليه وحده في جلب المصالح ودرء المفاسد. وهو ضمنياً يتضمن الكفالة والرعاية الكاملة لمن توكل عليه.", explanation: "يُستفاد منه في باب شرح الأسماء. يُستفاد منه في باب شرح الأسماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1625", section: "الأسماء الحسنى", category: "الأسماء الحسنى عموماً", level: "سهل", question: "كم اسماً من أسماء الله الحسنى وردت في الحديث المشهور عند الترمذي وابن ماجه؟", answer: "تسعة وتسعون اسماً في حديث: «إن لله تسعة وتسعين اسماً مئةً إلا واحداً من أحصاها دخل الجنة» (البخاري ومسلم). غير أن العلماء اختلفوا في تعداد تلك الأسماء لأن الحديث في الصحيحين لم يذكرها، بل ذِكرها في رواية الترمذي من زيادة راوٍ يناقشها العلماء.", explanation: "يُستفاد منه في باب الأسماء الحسنى عموماً. يُستفاد منه في باب الأسماء الحسنى عموماً مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1626", section: "الأذكار والأدعية", category: "الصباح والمساء", level: "سهل", question: "ما الذكر الجامع الوارد في الصباح؟", answer: "«أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ» (رواه مسلم)، وكان النبي ﷺ يقوله إذا أمسى بلفظ: «أمسينا وأمسى الملك لله». ولا يثبت ترتيب معيَّن يجعل ذكراً بعينه «أول» أذكار الصباح، وإنما هي أذكار مأثورة يقولها المسلم في وقتها", explanation: "يُستفاد منه في باب الصباح والمساء. يُستفاد منه في باب الصباح والمساء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1627", section: "الأذكار والأدعية", category: "الصباح والمساء", level: "متوسط", question: "ما الوارد في فضل قراءة آية الكرسي؟", answer: "أثبتُ ما ورد فيها أنها حِرزٌ عند النوم؛ ففي حديث أبي هريرة رضي الله عنه في قصة الشيطان الذي كان يأخذ من تمر الصدقة أنه قال له: «إذا أويتَ إلى فراشك فاقرأ آية الكرسي، لن يزال عليك من الله حافظ، ولا يقربك شيطان حتى تصبح»، فقال النبي ﷺ: «صدَقَك وهو كذوب» (رواه البخاري). وأمّا تخصيصها بالصباح والمساء فجاء من طرق أخرى تكلَّم أهل العلم في ثبوتها، والأصل المحفوظ في فضلها ما تقدَّم", explanation: "يُستفاد منه في باب الصباح والمساء. يُستفاد منه في باب الصباح والمساء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1628", section: "الأذكار والأدعية", category: "الصلاة", level: "سهل", question: "ما يُقال في الركوع؟", answer: "«سُبْحَانَ رَبِّيَ الْعَظِيمِ»؛ ثبت من فعله ﷺ في حديث حذيفة بن اليمان رضي الله عنه في وصف صلاته بالليل (رواه مسلم)، وأدنى الكمال ثلاث مرات. وهو واجب عند الحنابلة، سنة عند جمهور الفقهاء لا تبطل الصلاة بتركه", explanation: "يُستفاد منه في باب الصلاة. يُستفاد منه في باب الصلاة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1629", section: "الأذكار والأدعية", category: "الصلاة", level: "سهل", question: "ما يُقال في السجود؟", answer: "«سُبْحَانَ رَبِّيَ الْأَعْلَى»؛ ثبت من فعله ﷺ في حديث حذيفة بن اليمان رضي الله عنه (رواه مسلم)، وأدنى الكمال ثلاث مرات. وحكمه كحكم تسبيح الركوع: واجب عند الحنابلة، سنة عند الجمهور. ويُستحب الإكثار من الدعاء في السجود لقوله ﷺ: «وأمّا السجود فاجتهدوا في الدعاء، فقَمِنٌ أن يُستجاب لكم» (رواه مسلم)", explanation: "يُستفاد منه في باب الصلاة. يُستفاد منه في باب الصلاة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1630", section: "الأذكار والأدعية", category: "بعد الصلاة", level: "متوسط", question: "ما فضل التسبيح والتحميد والتكبير ثلاثاً وثلاثين بعد الصلاة، وبمَ تُتمّ المائة؟", answer: "غُفرت خطاياه وإن كانت مثل زبد البحر — بشرط أن يُتمّ المائة بالتهليل؛ ففي حديث أبي هريرة رضي الله عنه: «من سبَّح الله في دُبُر كل صلاة ثلاثاً وثلاثين، وحمِد الله ثلاثاً وثلاثين، وكبَّر الله ثلاثاً وثلاثين، فتلك تسعة وتسعون، وقال تمام المائة: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير — غُفرت خطاياه وإن كانت مثل زبد البحر» (رواه مسلم: ٥٩٧). فالفضل مرتَّب على إتمام المائة بالتهليل لا على التسع والتسعين وحدها", explanation: "يُستفاد منه في باب بعد الصلاة. يُستفاد منه في باب بعد الصلاة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1631", section: "الأذكار والأدعية", category: "دعاء الكرب", level: "سهل", question: "ما دعاء الكرب الوارد عن النبي ﷺ بتمامه؟", answer: "«لا إله إلا الله العظيم الحليم، لا إله إلا الله ربّ العرش العظيم، لا إله إلا الله ربّ السماوات وربّ الأرض وربّ العرش الكريم»؛ كان النبي ﷺ يدعو به عند الكرب (متفق عليه: البخاري ٦٣٤٦، مسلم ٢٧٣٠). وتنبيه: الجملة الثالثة من متن الحديث فلا يُقتصر على الجملتين الأوليين", explanation: "يُستفاد منه في باب دعاء الكرب. يُستفاد منه في باب دعاء الكرب مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1632", section: "الأذكار والأدعية", category: "دعاء الكرب", level: "متوسط", question: "ما الذكر الوارد عند المصيبة، وما فضله؟", answer: "«إنّا لله وإنّا إليه راجعون، اللهمّ أْجُرني في مصيبتي، وأَخْلِفْ لي خيرًا منها»؛ قال ﷺ: «ما من مسلم تصيبه مصيبة فيقول ما أمره الله... إلا أخلف الله له خيرًا منها» (رواه مسلم ٩١٨ من حديث أمّ سلمة رضي الله عنها، وفيه أنّها قالتها فأخلف الله لها رسولَ الله ﷺ). وأصل الاسترجاع قوله تعالى: ﴿الَّذِينَ إِذَا أَصَابَتْهُم مُّصِيبَةٌ قَالُوا إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ﴾ (البقرة: ١٥٦)", explanation: "يُستفاد منه في باب دعاء الكرب. يُستفاد منه في باب دعاء الكرب مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1633", section: "الأذكار والأدعية", category: "الاستغفار", level: "سهل", question: "ما سيّد الاستغفار بتمام لفظه، وما فضله؟", answer: "«اللهمّ أنت ربّي لا إله إلا أنت، خلقتني وأنا عبدك، وأنا على عهدك ووعدك ما استطعت، أعوذ بك من شرّ ما صنعت، أبوء لك بنعمتك عليّ وأبوء بذنبي، فاغفر لي فإنّه لا يغفر الذنوب إلا أنت». وفضله في تمام الحديث: «من قالها من النهار موقنًا بها فمات من يومه قبل أن يُمسي فهو من أهل الجنة، ومن قالها من الليل وهو موقن بها فمات قبل أن يُصبح فهو من أهل الجنة» (رواه البخاري ٦٣٠٦ من حديث شدّاد بن أوس رضي الله عنه)", explanation: "يُستفاد منه في باب الاستغفار. يُستفاد منه في باب الاستغفار مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1634", section: "الأذكار والأدعية", category: "الاستغفار", level: "متوسط", question: "كم كان النبي ﷺ يستغفر الله في اليوم؟", answer: "جاء ذلك بروايتين لا تعارض بينهما: «والله إنّي لأستغفر الله وأتوب إليه في اليوم أكثر من سبعين مرّة» (رواه البخاري ٦٣٠٧)، و«إنّه ليُغان على قلبي، وإنّي لأستغفر الله في اليوم مئة مرّة» (رواه مسلم ٢٧٠٢) — وجمع أهل العلم بينهما بأنّ ذلك يختلف باختلاف الأحوال والأوقات، وأنّ ذكر العدد لا يُراد به الحصر. وليس العدد شرطًا في الفضل، وإنّما المقصود الإكثار؛ وهو ﷺ مغفور له ما تقدّم من ذنبه وما تأخّر، فاستغفاره تعبّدٌ وشكرٌ وتعليمٌ للأمة", explanation: "يُستفاد منه في باب الاستغفار. يُستفاد منه في باب الاستغفار مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1635", section: "الأذكار والأدعية", category: "الصلاة على النبي", level: "سهل", question: "ما الصلاة الإبراهيمية بتمامها، ومتى تُقال؟", answer: "«اللهمّ صلِّ على محمد وعلى آل محمد كما صلّيت على إبراهيم وعلى آل إبراهيم إنّك حميد مجيد، اللهمّ بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنّك حميد مجيد». وأصلها أنّ الصحابة سألوا: كيف نصلّي عليك؟ فعلّمهم إيّاها (متفق عليه: البخاري ٣٣٧٠، مسلم ٤٠٦ من حديث كعب بن عُجرة رضي الله عنه). ومحلّها المتأكِّد في التشهد الأخير من الصلاة، وتُقال في كل حين", explanation: "يُستفاد منه في باب الصلاة على النبي. يُستفاد منه في باب الصلاة على النبي مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1636", section: "الأذكار والأدعية", category: "الصلاة على النبي", level: "متوسط", question: "ما فضل الصلاة على النبي ﷺ، وما معنى صلاة الله على عبده؟", answer: "قال ﷺ: «من صلّى عليّ صلاةً واحدةً صلّى الله عليه بها عشرًا» (رواه مسلم ٤٠٨ من حديث أبي هريرة رضي الله عنه). ومعنى صلاة الله على عبده كما فسّره أبو العالية — وعلّقه البخاري في صحيحه — : «ثناؤه عليه في الملأ الأعلى»، لا الدعاء؛ فليست صلاة الله كصلاة العباد. والأمر بها في قوله تعالى: ﴿إِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ ۚ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا﴾ (الأحزاب: ٥٦)", explanation: "يُستفاد منه في باب الصلاة على النبي. يُستفاد منه في باب الصلاة على النبي مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1637", section: "الأذكار والأدعية", category: "التسبيح", level: "سهل", question: "ما معنى «سبحان الله»؟", answer: "تنزيه الله عزّ وجلّ عن كلّ نقص وعيب، وعمّا لا يليق بجلاله، وعمّا يصفه به الجاحدون؛ وأصلها في اللغة من «السَّبْح» بمعنى البُعد، فمعناها تبعيد الله عن السوء. وهي مقرونة بالحمد في القرآن على ألسنة الملائكة: ﴿وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ﴾ (البقرة: ٣٠)، والتنزيه وحده لا يكفي حتى يُقرَن بإثبات صفات الكمال", explanation: "يُستفاد منه في باب التسبيح. يُستفاد منه في باب التسبيح مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1638", section: "الأذكار والأدعية", category: "التسبيح", level: "متوسط", question: "ما الكلمتان الخفيفتان على اللسان الثقيلتان في الميزان؟", answer: "قال ﷺ: «كلمتان خفيفتان على اللسان، ثقيلتان في الميزان، حبيبتان إلى الرحمن: سبحان الله وبحمده، سبحان الله العظيم» (متفق عليه: البخاري ٦٦٨٢، مسلم ٢٦٩٤ من حديث أبي هريرة رضي الله عنه). ولا يعارض هذا حديث: «ما من شيء أثقل في ميزان المؤمن يوم القيامة من خُلُقٍ حسن»، فذاك في أعمال الجوارح والأخلاق، وهذا في الكلمتين من الذكر", explanation: "يُستفاد منه في باب التسبيح. يُستفاد منه في باب التسبيح مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1639", section: "الأذكار والأدعية", category: "الدعاء", level: "سهل", question: "ما شروط إجابة الدعاء وموانعها؟", answer: "ليست على درجة واحدة، فمنها شرطٌ ومنها مانع: فالشرط إخلاص الدعاء لله وحده وسؤاله دون سواه، وحضور القلب؛ قال تعالى: ﴿ادْعُونِي أَسْتَجِبْ لَكُمْ﴾ (غافر: ٦٠)، وقال ﷺ: «الدعاء هو العبادة» (الترمذي ٢٩٦٩، صححه الألباني). وأما لفظ «ادعوا الله وأنتم موقنون بالإجابة» فضعيف عند المحققين فلا يُستقل به شرطًا. والموانع أظهرها اثنان: الاستعجال، قال ﷺ: «يُستجاب لأحدكم ما لم يعجل، يقول: دعوتُ فلم يُستجب لي» (متفق عليه: البخاري ٦٣٤٠، مسلم ٢٧٣٥)؛ والمطعم الحرام، ففي حديث مسلم (١٠١٥) ذكر ﷺ الرجل يُطيل السفر أشعثَ أغبرَ يمدّ يديه إلى السماء ثم قال: «ومطعمه حرام، ومشربه حرام، وملبسه حرام، وغُذي بالحرام، فأنّى يُستجاب لذلك؟». وأمَر الله الداعيَ بالاستجابة له: ﴿فَلْيَسْتَجِيبُوا لِي وَلْيُؤْمِنُوا بِي لَعَلَّهُمْ يَرْشُدُونَ﴾ (البقرة: ١٨٦). ثمّ الإجابة لا تتخلّف: إمّا أن يُعجَّل له دعوته، أو تُدَّخر له في الآخرة، أو يُصرف عنه من السوء مثلها", explanation: "يُستفاد منه في باب الدعاء. يُستفاد منه في باب الدعاء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1640", section: "الأذكار والأدعية", category: "الدعاء", level: "متوسط", question: "ما أوقات إجابة الدعاء الثابتة، وما القيد في ساعة الجمعة؟", answer: "من أشهرها: جوف الليل الآخر — لحديث النزول: «ينزل ربّنا تبارك وتعالى كلّ ليلة إلى السماء الدنيا حين يبقى ثلث الليل الآخر فيقول: من يدعوني فأستجيب له» (متفق عليه: البخاري ١١٤٥)؛ وساعة يوم الجمعة: «فيه ساعة لا يوافقها عبد مسلم وهو قائم يصلّي يسأل الله شيئًا إلا أعطاه إيّاه» (متفق عليه: البخاري ٩٣٥، مسلم ٨٥٢) — وتعيينها محلّ خلافٍ بين أهل العلم، وأقواها قولان: ما بين جلوس الإمام إلى انقضاء الصلاة، وآخر ساعة بعد العصر؛ وبين الأذان والإقامة: «الدعاء لا يُردّ بين الأذان والإقامة» (أبو داود ٥٢١ والترمذي ٢١٢، حسّنه الألباني)؛ وحال السجود: «أقرب ما يكون العبد من ربّه وهو ساجد، فأكثِروا الدعاء» (رواه مسلم ٤٨٢). وتُضاف مواطن أخرى كدُبُر الصلوات المكتوبة، وعند نزول الغيث، وفي السفر، ودعوة الصائم", explanation: "يُستفاد منه في باب الدعاء. يُستفاد منه في باب الدعاء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1641", section: "الأذكار والأدعية", category: "الدعاء", level: "متوسط", question: "ما دعاء الاستخارة بتمامه، وما صفتها؟", answer: "صفتها أن يركع ركعتين من غير الفريضة ثم يقول: «اللهمّ إنّي أستخيرك بعلمك، وأستقدرك بقدرتك، وأسألك من فضلك العظيم، فإنّك تقدِر ولا أقدِر، وتعلم ولا أعلم، وأنت علّام الغيوب. اللهمّ إن كنت تعلم أنّ هذا الأمر خيرٌ لي في ديني ومعاشي وعاقبة أمري فاقدُره لي ويسّره لي ثمّ بارك لي فيه، وإن كنت تعلم أنّ هذا الأمر شرٌّ لي في ديني ومعاشي وعاقبة أمري فاصرفه عنّي واصرفني عنه، واقدُر لي الخير حيث كان ثمّ أرضِني به» — ويُسمّي حاجته موضع «هذا الأمر». وأصله حديث جابر بن عبدالله رضي الله عنهما: «كان رسول الله ﷺ يعلّمنا الاستخارة في الأمور كلّها كما يعلّمنا السورة من القرآن» (رواه البخاري ١١٦٢)", explanation: "يُستفاد منه في باب الدعاء. يُستفاد منه في باب الدعاء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1642", section: "الأذكار والأدعية", category: "الحوقلة", level: "سهل", question: "ما معنى «لا حول ولا قوّة إلا بالله»؟", answer: "تفويض الأمر إلى الله والتبرّؤ من الحول والقوّة إلا به؛ فـ«الحول» التحوّل من حال إلى حال، و«القوّة» الطاقة والقدرة. ومن أشهر ما فُسّرت به عند أهل العلم: لا تحوُّل عن معصية الله إلا بعصمته، ولا قوّة على طاعته إلا بمعونته. فهي كلمة استسلامٍ وتوكّلٍ لا كلمة عجزٍ وقعود، ولذلك شُرعت عند مباشرة الأسباب كالخروج من البيت: «بسم الله، توكّلتُ على الله، ولا حول ولا قوّة إلا بالله» (رواه أبو داود والترمذي)", explanation: "يُستفاد منه في باب الحوقلة. يُستفاد منه في باب الحوقلة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1643", section: "الأذكار والأدعية", category: "الحوقلة", level: "متوسط", question: "ما فضل «لا حول ولا قوّة إلا بالله»، وبمَ وصفها النبي ﷺ؟", answer: "وصفها بأنّها كنزٌ من كنوز الجنة؛ قال ﷺ لأبي موسى الأشعري رضي الله عنه: «يا عبدالله بن قيس، ألا أدلّك على كنزٍ من كنوز الجنة؟ — قلت: بلى يا رسول الله. قال: لا حول ولا قوّة إلا بالله» (متفق عليه: البخاري ٦٣٨٤، مسلم ٢٧٠٤). وسمّاها كنزًا لعِظَم ثوابها المدَّخر لصاحبها كما يُدَّخر الكنز", explanation: "يُستفاد منه في باب الحوقلة. يُستفاد منه في باب الحوقلة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1644", section: "الأذكار والأدعية", category: "التوبة", level: "سهل", question: "ما شروط التوبة الصحيحة؟", answer: "شروطها ثلاثة في كل توبة: الإقلاع عن الذنب، والندم على ما مضى، والعزم على ألّا يعود إليه. فإن كان الذنب متعلقًا بحقّ آدميّ زِيد شرط رابع خاصّ به: ردّ الحقّ أو الاستحلال من صاحبه. قال تعالى: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ تُوبُوٓا۟ إِلَى ٱللَّهِ تَوْبَةًۭ نَّصُوحًا﴾ (التحريم: ٨)", explanation: "يُستفاد منه في باب التوبة. يُستفاد منه في باب التوبة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1645", section: "الأذكار والأدعية", category: "التوبة", level: "متوسط", question: "ما الفرق بين التوبة والاستغفار؟", answer: "الاستغفار طلب المغفرة، والتوبة الرجوع إلى الله بترك الذنب والندم عليه والعزم على ألّا يعود؛ فقد يستغفر العبد بلسانه وهو مقيم على ذنبه، ولا تصحّ التوبة مع الإقامة عليه", explanation: "يُستفاد منه في باب التوبة. يُستفاد منه في باب التوبة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1646", section: "الأذكار والأدعية", category: "الشكر", level: "سهل", question: "ما فضل الحمد لله؟", answer: "أنها تملأ الميزان، لقوله ﷺ: «الطُّهورُ شطرُ الإيمانِ، والحمدُ للهِ تملأُ الميزانَ، وسبحانَ اللهِ والحمدُ للهِ تملآنِ — أو تملأُ — ما بينَ السماواتِ والأرضِ» (مسلم ٢٢٣)", explanation: "يُستفاد منه في باب الشكر. يُستفاد منه في باب الشكر مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1647", section: "الأذكار والأدعية", category: "الشكر", level: "متوسط", question: "ما دعاء شكر النعمة؟", answer: "«الحمدُ للهِ الذي بنعمتِه تتمُّ الصالحاتُ» — كان النبي ﷺ إذا رأى ما يُسرّه قالها، وإذا رأى ما يكره قال: «الحمدُ للهِ على كلِّ حالٍ» (ابن ماجه ٣٨٠٣، وحسّنه الألباني)", explanation: "يُستفاد منه في باب الشكر. يُستفاد منه في باب الشكر مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1648", section: "الأذكار والأدعية", category: "العوذ", level: "سهل", question: "بم يُستعاذ من الشيطان؟", answer: "«أعوذ بالله من الشيطان الرجيم»، لقوله تعالى: ﴿فَإِذَا قَرَأْتَ ٱلْقُرْءَانَ فَٱسْتَعِذْ بِٱللَّهِ مِنَ ٱلشَّيْطَٰنِ ٱلرَّجِيمِ﴾ (النحل: ٩٨)", explanation: "يُستفاد منه في باب العوذ. يُستفاد منه في باب العوذ مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1649", section: "الأذكار والأدعية", category: "عام", level: "سهل", question: "ما أفضل الأذكار وأجمعها؟ وما ثوابها؟", answer: "من أفضل الأذكار وأجمعها: قال ﷺ: «كلمتان خفيفتان على اللسان، ثقيلتان في الميزان، حبيبتان إلى الرحمن: سبحان الله وبحمده، سبحان الله العظيم» (متفق عليه: البخاري ٦٤٠٦، مسلم ٢٦٩٤) — وهذا لفظه، فتقديم «خفيفتان» على «ثقيلتان» هو الوارد. وقال ﷺ: «أفضل الذكر لا إله إلا الله، وأفضل الدعاء الحمد لله» (رواه الترمذي ٣٣٨٣ وحسّنه). و«الباقيات الصالحات» فُسِّرت بقوله ﷺ: «سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر... وهنّ الباقيات الصالحات» — رواه أحمد والنسائي والحاكم وصححه على شرط مسلم، وصححه الألباني، وليس في الصحيحين.", explanation: "يُستفاد منه في باب عام. يُستفاد منه في باب عام مع الرجوع إلى مراجع مجالس العلم. الجواب يُختبر فهم الأذكار والأدعية لا الحفظ اللفظي فقط.", reference: "مراجع مجالس العلم" },
  { id: "1650", section: "الأذكار والأدعية", category: "عام", level: "متوسط", question: "ما الفرق بين الذِّكر والدعاء؟ وما أيهما أفضل؟", answer: "الذِّكر: هو كل قول يُذكر الله به من تسبيح وتهليل وتكبير وتحميد وتلاوة. والدعاء: هو طلب العبد من ربه الحاجات وصرف المضار وجلب المنافع. أيهما أفضل؟ اختلف العلماء: ذهب ابن تيمية وابن القيم إلى أن الذِّكر الخالص أفضل من الدعاء في الجملة، لأن الذكر ثناء على الله وهو حق الله الخالص، والدعاء حظّ العبد من ربه. وكلاهما عبادة عظيمة يُثاب عليها المسلم.", explanation: "يُستفاد منه في باب عام. يُستفاد منه في باب عام مع الرجوع إلى مراجع مجالس العلم. الجواب يُختبر فهم الأذكار والأدعية لا الحفظ اللفظي فقط.", reference: "مراجع مجالس العلم" },
  { id: "1651", section: "علوم القرآن", category: "المكي والمدني", level: "سهل", question: "ما الفرق بين السور المكية والسور المدنية؟", answer: "المعتمد عند جمهور أهل العلم اعتبار زمن النزول: فالمكيّ ما نزل قبل هجرة النبي ﷺ ولو نزل بغير مكة، والمدنيّ ما نزل بعد الهجرة ولو نزل بمكة؛ ولذلك عُدّ قوله تعالى ﴿ٱلْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ﴾ [المائدة: 3] مدنيًّا وقد نزل بعرفة في حجة الوداع. وقيل في ضبطهما بالمكان (ما نزل بمكة وما نزل بالمدينة) وبالمخاطَبين (يا أيها الناس/يا أيها الذين آمنوا)، وكلاهما غير مطّرد", explanation: "يُستفاد منه في باب المكي والمدني. يُستفاد منه في باب المكي والمدني مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1652", section: "علوم القرآن", category: "السبع المثاني", level: "سهل", question: "ما السبع المثاني في قوله تعالى: ﴿وَلَقَدْ ءَاتَيْنَٰكَ سَبْعًۭا مِّنَ ٱلْمَثَانِى وَٱلْقُرْءَانَ ٱلْعَظِيمَ﴾ [الحجر: 87]؟", answer: "هي سورة الفاتحة، وهو الثابت المرفوع في حديث أبي سعيد بن المُعلّى رضي الله عنه أن النبي ﷺ قال له: «الحمد لله رب العالمين هي السبع المثاني والقرآن العظيم الذي أوتيته» (رواه البخاري في فضائل القرآن). وقيل: هي السبع الطُّوَل، ورُوي عن ابن مسعود وابن عباس رضي الله عنهم، والأول أصحّ لثبوته مرفوعًا. وأشهر ما قيل في وجه التسمية بالمثاني أنها تُثنى أي تُكرَّر في كل ركعة، وهو أحد أقوال أهل العلم", explanation: "يُستفاد منه في باب السبع المثاني. يُستفاد منه في باب السبع المثاني مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1653", section: "علوم القرآن", category: "جمع القرآن", level: "متوسط", question: "من تولى جمع القرآن الكريم في عهد أبي بكر الصديق رضي الله عنه؟", answer: "زيد بن ثابت الأنصاري رضي الله عنه؛ وكان ذلك بمشورة عمر بن الخطاب رضي الله عنه بعد استحرار القتل بالقُرّاء يوم اليمامة، فجُمع القرآن في صُحُف بقيت عند أبي بكر ثم عمر ثم حفصة بنت عمر رضي الله عنهم، والقصة في صحيح البخاري (٤٩٨٦). وهو غير جمع عثمان رضي الله عنه الذي نسخ منها المصاحف وأرسلها إلى الأمصار (البخاري ٤٩٨٧)", explanation: "يُستفاد منه في باب جمع القرآن. يُستفاد منه في باب جمع القرآن مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1654", section: "علوم القرآن", category: "جمع القرآن", level: "متوسط", question: "في عهد من تمّ توحيد المصحف وإرسال نسخ منه إلى الأمصار؟", answer: "في عهد عثمان بن عفان رضي الله عنه، فنُسخت المصاحف العثمانية وأُرسلت إلى الأمصار", explanation: "يُستفاد منه في باب جمع القرآن. يُستفاد منه في باب جمع القرآن مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1655", section: "علوم القرآن", category: "أسباب النزول", level: "متوسط", question: "ما المقصود بأسباب النزول؟", answer: "الحوادث والأسئلة والوقائع التي كانت سبباً في نزول آية أو آيات من القرآن الكريم", explanation: "يُستفاد منه في باب أسباب النزول. يُستفاد منه في باب أسباب النزول مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1656", section: "علوم القرآن", category: "إحصاءات القرآن", level: "سهل", question: "كم عدد أجزاء القرآن الكريم وكم عدد سوره؟", answer: "القرآن 30 جزءاً و114 سورة و6236 آية — إحصاءات القرآن الكريم المعتمدة.", explanation: "يُستفاد منه في باب إحصاءات القرآن. يُستفاد منه في باب إحصاءات القرآن مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1657", section: "علوم القرآن", category: "المحكم والمتشابه", level: "صعب", question: "ما الفرق بين المحكم والمتشابه في القرآن الكريم؟", answer: "المحكم ما وضح معناه ولا يحتمل غيره، والمتشابه ما احتمل معاني متعددة ويحتاج إلى تدبر وتأويل", explanation: "يُستفاد منه في باب المحكم والمتشابه. يُستفاد منه في باب المحكم والمتشابه مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1658", section: "علوم القرآن", category: "التفسير", level: "متوسط", question: "ما الفرق بين التفسير بالمأثور والتفسير بالرأي؟", answer: "التفسير بالمأثور: ما جاء عن النبي ﷺ والصحابة والتابعين. التفسير بالرأي: ما يُستنبَط بالاجتهاد والنظر مع الشروط العلمية", explanation: "يُستفاد منه في باب التفسير. يُستفاد منه في باب التفسير مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1659", section: "علوم القرآن", category: "النسخ", level: "صعب", question: "ما النسخ في علوم القرآن؟", answer: "رفع حكم شرعي أو تلاوة بدليل شرعي متأخر، وله أنواع: نسخ الحكم دون التلاوة، ونسخ التلاوة دون الحكم، ونسخهما معاً", explanation: "يُستفاد منه في باب النسخ. يُستفاد منه في باب النسخ مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1660", section: "علوم القرآن", category: "الإعجاز", level: "متوسط", question: "ما أنواع الإعجاز القرآني؟", answer: "الإعجاز البياني والبلاغي، والإعجاز التشريعي، والإعجاز العلمي، والإعجاز الغيبي، والإعجاز العددي عند بعض العلماء", explanation: "يُستفاد منه في باب الإعجاز. يُستفاد منه في باب الإعجاز مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1661", section: "علوم القرآن", category: "أسباب النزول", level: "متوسط", question: "ما فائدة معرفة أسباب نزول القرآن؟", answer: "فهم الآيات وتفسيرها الصحيح، ومعرفة الحكمة من التشريع، وتحديد المقصود بالعام والخاص، ودفع الإشكالات", explanation: "يُستفاد منه في باب أسباب النزول. يُستفاد منه في باب أسباب النزول مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1662", section: "علوم القرآن", category: "الناسخ والمنسوخ", level: "صعب", question: "ما تعريف النسخ في القرآن الكريم؟", answer: "رفع الحكم الشرعي بدليل شرعي متأخر عنه. النسخ في القرآن نوعان: نسخ التلاوة دون الحكم، ونسخ الحكم دون التلاوة", explanation: "يُستفاد منه في باب الناسخ والمنسوخ. يُستفاد منه في باب الناسخ والمنسوخ مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1663", section: "علوم القرآن", category: "المحكم والمتشابه", level: "متوسط", question: "ما الفرق بين المحكم والمتشابه في القرآن؟", answer: "المحكم: ما اتضح معناه ولا لبس فيه. المتشابه: ما خفي معناه واحتمل تأويلات. قال تعالى: هو الذي أنزل عليك الكتاب منه آيات محكمات هن أم الكتاب وأخر متشابهات", explanation: "يُستفاد منه في باب المحكم والمتشابه. يُستفاد منه في باب المحكم والمتشابه مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1664", section: "علوم القرآن", category: "الإعجاز", level: "متوسط", question: "ما وجوه إعجاز القرآن الكريم؟", answer: "الإعجاز اللغوي والبياني، والإعجاز التشريعي، والإعجاز العلمي، والإعجاز الغيبي، والتحدي المستمر للإنس والجن على الإتيان بمثله", explanation: "يُستفاد منه في باب الإعجاز. يُستفاد منه في باب الإعجاز مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" }
];

